def anti_fib(n: int) -> int:
    """O(1) computation of the n-th anti-Fibonacci term."""
    return n + n // 2 + 1

def greedy_avoidance(init: tuple[int,int], count: int) -> list[int]:
    seq = list(init)
    forbidden = {init[0] + init[1]}
    for _ in range(count - 2):
        c = seq[-1] + 1
        while c in forbidden:
            c += 1
        forbidden.add(seq[-1] + c)
        seq.append(c)
    return seq

def inverse_anti_fib(k: int):
    if k <= 0 or k % 3 == 0:
        return None
    r = k % 3
    j = (k - r) // 3
    return 2 * j if r == 1 else 2 * j + 1
